function numDistinctIslands2(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const seen = grid.map(row => row.map(() => false));
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const transforms = [
    ([r, c]) => [r, c], ([r, c]) => [r, -c], ([r, c]) => [-r, c], ([r, c]) => [-r, -c],
    ([r, c]) => [c, r], ([r, c]) => [c, -r], ([r, c]) => [-c, r], ([r, c]) => [-c, -r]
  ];

  const canonical = cells => {
    let smallest = null;
    for (const transform of transforms) {
      const moved = cells.map(transform);
      moved.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
      const [baseRow, baseCol] = moved[0];
      const key = moved.map(([r, c]) => `${r - baseRow},${c - baseCol}`).join(';');
      if (smallest === null || key < smallest) {
        smallest = key;
      }
    }
    return smallest;
  };

  const shapes = new Set();
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] === 0 || seen[r][c]) {
        continue;
      }
      const cells = [];
      const stack = [[r, c]];
      seen[r][c] = true;
      while (stack.length > 0) {
        const [y, x] = stack.pop();
        cells.push([y, x]);
        for (const [dy, dx] of directions) {
          const ny = y + dy;
          const nx = x + dx;
          if (ny >= 0 && ny < rows && nx >= 0 && nx < cols && grid[ny][nx] === 1 && !seen[ny][nx]) {
            seen[ny][nx] = true;
            stack.push([ny, nx]);
          }
        }
      }
      shapes.add(canonical(cells));
    }
  }
  return shapes.size;
}

