function numDistinctIslands2(grid) {
  // Collect islands with BFS, then compare each one against the shapes kept so far under all 8 symmetries.
  const rows = grid.length;
  const cols = grid[0].length;
  const owner = grid.map(row => row.map(() => -1));
  const islands = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== 1 || owner[r][c] !== -1) continue;
      const id = islands.length;
      const queue = [[r, c]];
      owner[r][c] = id;
      for (let head = 0; head < queue.length; head++) {
        const [y, x] = queue[head];
        for (const [ny, nx] of [[y - 1, x], [y + 1, x], [y, x - 1], [y, x + 1]]) {
          if (ny < 0 || nx < 0 || ny >= rows || nx >= cols || grid[ny][nx] !== 1 || owner[ny][nx] !== -1) continue;
          owner[ny][nx] = id;
          queue.push([ny, nx]);
        }
      }
      islands.push(queue);
    }
  }
  const normalize = cells => {
    const minR = Math.min(...cells.map(p => p[0]));
    const minC = Math.min(...cells.map(p => p[1]));
    return new Set(cells.map(([a, b]) => (a - minR) * 1000 + (b - minC)));
  };
  const sameSet = (a, b) => a.size === b.size && [...a].every(v => b.has(v));
  const variants = cells => {
    const out = [];
    let current = cells;
    for (let turn = 0; turn < 4; turn++) {
      out.push(normalize(current));
      out.push(normalize(current.map(([a, b]) => [a, -b])));
      current = current.map(([a, b]) => [b, -a]);
    }
    return out;
  };
  const kept = [];
  for (const island of islands) {
    const all = variants(island);
    if (!kept.some(shape => all.some(v => sameSet(v, shape)))) kept.push(normalize(island));
  }
  return kept.length;
}

