function generate(rand, size) {
  const large = size === 'large';
  const rows = large ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 7);
  const cols = large ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 7);
  const grid = Array.from({ length: rows }, () => new Array(cols).fill(0));
  if (rand() < 0.5) {
    const density = 0.2 + rand() * 0.5;
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) grid[r][c] = rand() < density ? 1 : 0;
    return [grid];
  }
  // Stamp rotated and mirrored copies of a few random shapes, keeping the copies apart.
  const shapes = [];
  const kinds = large ? 6 : 2;
  for (let s = 0; s < kinds; s++) {
    const cells = [[0, 0]];
    const target = 1 + Math.floor(rand() * (large ? 8 : 4));
    while (cells.length < target) {
      const [r, c] = cells[Math.floor(rand() * cells.length)];
      const [dr, dc] = [[1, 0], [-1, 0], [0, 1], [0, -1]][Math.floor(rand() * 4)];
      if (!cells.some(([a, b]) => a === r + dr && b === c + dc)) cells.push([r + dr, c + dc]);
    }
    shapes.push(cells);
  }
  const attempts = large ? 400 : 12;
  for (let t = 0; t < attempts; t++) {
    const flip = rand() < 0.5 ? -1 : 1;
    let cells = shapes[Math.floor(rand() * shapes.length)].map(([r, c]) => [r, c * flip]);
    const turns = Math.floor(rand() * 4);
    for (let q = 0; q < turns; q++) cells = cells.map(([r, c]) => [c, -r]);
    const minR = Math.min(...cells.map(p => p[0]));
    const minC = Math.min(...cells.map(p => p[1]));
    const offR = Math.floor(rand() * rows);
    const offC = Math.floor(rand() * cols);
    const placed = cells.map(([r, c]) => [r - minR + offR, c - minC + offC]);
    const free = placed.every(([r, c]) => r < rows && c < cols && [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]].every(([dr, dc]) => {
      const y = r + dr, x = c + dc;
      return y < 0 || y >= rows || x < 0 || x >= cols || grid[y][x] === 0;
    }));
    if (free) for (const [r, c] of placed) grid[r][c] = 1;
  }
  return [grid];
}
